CASE malformed JSON
REQUEST_BODY {"broken":
STATUS 400
RESPONSE {"error": {"code": "invalid_json", "message": "request body must be valid JSON"}}
CASE empty operating_points
REQUEST_BODY {"operating_points":[],"dropout_curve":[]}
STATUS 422
RESPONSE {"error": {"code": "invalid_operating_points", "message": "operating_points must be a non-empty array"}}
CASE unordered dropout_curve
REQUEST_BODY {"operating_points":[{"duration_s":1800.0,"input_voltage_v":5.0,"requested_output_voltage_v":3.3,"output_current_a":0.0}],"dropout_curve":[{"output_current_a":1,"dropout_voltage_v":0.2},{"output_current_a":0,"dropout_voltage_v":0.1}]}
STATUS 422
RESPONSE {"error": {"code": "invalid_dropout_curve", "message": "dropout curve output_current_a must be strictly increasing"}}
