REQUEST_BODY {"operating_points":[{"duration_s":1800.0,"input_voltage_v":5.0,"requested_output_voltage_v":3.3,"output_current_a":0.0}],"dropout_curve":[{"output_current_a":0.0,"dropout_voltage_v":0.1},{"output_current_a":1.0,"dropout_voltage_v":0.3},{"output_current_a":2.0,"dropout_voltage_v":0.5}],"quiescent_current_a":-0.1}
